contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address depositor, address other, uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1)); require(amount1 <= 1000000000000000000000000000000);
        require(depositor != address(this) && other != address(this) && depositor != other);
        require(amount1 > 0);
        require(address(this).balance >= amount1);

        uint balanceBefore = address(c).balance;

        c.deposit{value: amount1}(); if (__ESBMC_reverted()) return;

        uint balanceAfter = address(c).balance;

        // Verify the rule by attempting a withdrawAll from the depositor and checking the received ether.
        uint thisBefore = address(this).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint thisAfter = address(this).balance;

        assert(balanceAfter == balanceBefore + amount1 && thisAfter == thisBefore + amount1);
    }
}

