// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(address depositor, address other, uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositor != address(this) && other != address(this) && depositor != other);
        vm.assume(amount1 > 0);
        vm.assume(address(this).balance >= amount1);
        uint balanceBefore = address(c).balance;
        try c.deposit{value: amount1}() {} catch { return; }
        uint balanceAfter = address(c).balance;
        uint thisBefore = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        uint thisAfter = address(this).balance;
        assertTrue(balanceAfter == balanceBefore + amount1 && thisAfter == thisBefore + amount1);
    }

    function testFuzz_run(address depositor, address other, uint256 amount1, uint256 amount2) public {
        vm.assume(depositor.code.length == 0 && uint160(depositor) > 0xffff && depositor != address(this) && depositor != address(c) && depositor != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && depositor != 0x000000000000000000636F6e736F6c652e6c6f67 && depositor != 0x4e59b44847b379578588920cA78FbF26c0B4956C && depositor != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(depositor, other, amount1, amount2);
    }

    receive() external payable {}
}
